custom_css:
/* ═══════════ 十二时辰·戌·爱 ｜ 戌时 19:00–21:00 ｜ 温柔 ═══════════
   花笺随水：角色消息是浮在夜水上的胡粉花笺，用户消息是一片群青水面。
   by if love
   字体：站酷小薇（名字/标题）· 思源宋体（正文）· Cormorant Garamond（点缀）
*/
@import url("https://cdn.jsdelivr.net/npm/@fontsource/zcool-xiaowei@5.3.0/400.css");
@import url("https://cdn.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/400.css");
@import url("https://cdn.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/600.css");
@import url("https://cdn.jsdelivr.net/npm/@fontsource/cormorant-garamond@5.3.0/400-italic.css");

/* ─────────── tokens ─────────── */
:root{
  --xu-blue:#1f3fae; --xu-deep:#122a78; --xu-night:#0f2468;
  --xu-ink:#2b3452; --xu-mist:#5a6b9b; --xu-faint:#8a96bd;
  --xu-silk:#f4f3ef; --xu-silk-2:#fbfaf7; --xu-paper:rgba(251,250,247,.96);
  --xu-gold:#c9a24a; --xu-gold-soft:#ecd79c;
  --xu-line:rgba(31,63,174,.28); --xu-line-soft:rgba(31,63,174,.14);
  --xu-wash:rgba(31,63,174,.06); --xu-wash-2:rgba(31,63,174,.11);
  --xu-focus:0 0 0 2px rgba(201,162,74,.7);
  --xu-shadow:0 10px 26px rgba(18,42,120,.22);
  --xu-shadow-sm:0 4px 12px rgba(18,42,120,.16);
  --xu-disabled:.45;
  --xu-ok:#2f6f8f; --xu-warn:#a97a26; --xu-err:#9b3550;
  --xu-title:'ZCOOL XiaoWei','Noto Serif SC','Source Han Serif SC','Songti SC','STSong',serif;
  --xu-body:'Noto Serif SC','Source Han Serif SC','Songti SC','STSong','SimSun',serif;
  --xu-latin:'Cormorant Garamond','Times New Roman',serif;
  --xu-noise:url("data:image/svg+xml;base64,");
  --xu-dust:url("data:image/svg+xml;base64,");
  --mainFontFamily:var(--xu-body);
  --SmartThemeCheckboxTickColor:#fbfaf7;
}

/* ─────────── 去掉官方黑色投影 / 文字光晕 ─────────── */
:root{--shadowWidth:0!important}
.mes_button,.extraMesButtons > div,.mes_edit_buttons,.drag-grabber,.dragClose,.ch_fav_icon,.mes_img_swipe_counter{filter:none!important}
.mes_button,.extraMesButtons > div{opacity:.6}
.mes_button:hover,.extraMesButtons > div:hover{opacity:1}
#chat > .welcomePanel .mes_button{filter:none!important;text-shadow:none!important}

/* ─────────── scrollbar (appearance only) ─────────── */
::-webkit-scrollbar{display:none!important}
*{scrollbar-width:none!important;-ms-overflow-style:none!important}

/* ─────────── background ─────────── */
body{background-color:var(--xu-silk)}
#bg1{background-image:url("data:image/svg+xml;base64,")!important;background-size:cover!important;background-position:center!important;background-color:var(--xu-silk)!important}
@media (max-width:1000px){#bg1{background-image:url("data:image/svg+xml;base64,")!important}}
::selection{background:rgba(201,162,74,.35);color:inherit}

/* ─────────── top bar ─────────── */
#top-bar{background:linear-gradient(180deg,var(--xu-night),#16308a)!important;border:0!important;
  box-shadow:0 1px 0 rgba(236,215,156,.35),0 6px 18px rgba(18,42,120,.25)!important;backdrop-filter:none!important}
#top-bar::before{content:"";position:absolute;inset:0;background:var(--xu-dust);opacity:.75;pointer-events:none}
#top-settings-holder .drawer-icon{color:#e9eeff!important;opacity:.82;filter:none!important;text-shadow:none!important}
#top-settings-holder .drawer-icon.closedIcon:hover{opacity:1;color:#fff!important}
#top-settings-holder .drawer-icon.openIcon{color:var(--xu-gold-soft)!important;opacity:1}
#top-settings-holder .drawer-toggle:focus-visible{outline:none;box-shadow:var(--xu-focus);border-radius:8px}

/* ─────────── chat shell ─────────── */
#sheld,#chat{background:transparent!important;backdrop-filter:none!important;border:0!important;box-shadow:none!important}
#chat{padding:16px 10px 18px!important}

/* ─────────── message: layout ─────────── */
#chat .mes:not(.smallSysMes){position:relative;flex-direction:column;align-items:stretch;padding:0!important;margin:30px 0 10px!important;
  border:0!important;background:none!important;box-shadow:none!important;backdrop-filter:none!important}
#chat .mes:not(.smallSysMes) > .mesAvatarWrapper{position:relative;z-index:2;align-self:flex-start;margin:0 0 -30px 14px;padding:0!important;
  display:flex;flex-direction:column;align-items:center;min-height:0!important}
#chat .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper{align-self:flex-end;margin:0 14px -30px 0}
#chat .mes .avatar{width:58px!important;height:58px!important;flex:none;border-radius:50%!important}
#chat .mes .avatar img{width:58px!important;height:58px!important;border:0!important;border-radius:50%!important;object-fit:cover;
  box-shadow:0 0 0 2.5px var(--xu-silk-2),0 0 0 3.5px var(--xu-blue),0 6px 14px rgba(18,42,120,.28)!important}
#chat .mes[is_user="true"] .avatar img{box-shadow:0 0 0 2.5px #16308a,0 0 0 3.5px var(--xu-gold-soft),0 6px 14px rgba(18,42,120,.28)!important}
/* 涟漪：头像落水 */
#chat .mes:not(.smallSysMes) > .mesAvatarWrapper::before{content:"";position:absolute;left:50%;top:40px;width:150px;height:56px;transform:translateX(-50%);
  background:url("data:image/svg+xml;base64,") center/contain no-repeat;pointer-events:none;z-index:-1}
#chat .mes[is_user="true"] > .mesAvatarWrapper::before{background-image:url("data:image/svg+xml;base64,")}
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{display:none!important}

/* 楼层 → 第 N 瓣 */
#chat .mes[is_system="false"]::before{content:"第 " attr(mesid) " 瓣";position:absolute;bottom:10px;left:50%;transform:translateX(-50%);z-index:3;pointer-events:none;
  font:12px/1 var(--xu-title);letter-spacing:.3em;color:var(--xu-blue);opacity:.55;white-space:nowrap}
#chat .mes[is_system="false"][mesid="0"]::before{content:"初 开"}
#chat .mes[is_user="true"][is_system="false"]::before{color:var(--xu-gold-soft);opacity:.8}
/* 梅枝 / 落瓣：越界装饰 */
#chat .mes[is_user="false"]:not(.smallSysMes)::after{content:"";position:absolute;right:-4px;top:-6px;width:74px;height:58px;z-index:3;
  background:url("data:image/svg+xml;base64,") center/contain no-repeat;pointer-events:none;filter:drop-shadow(0 3px 4px rgba(18,42,120,.25))}
#chat .mes[is_user="true"]:not(.smallSysMes)::after{content:"";position:absolute;left:-4px;bottom:-12px;width:32px;height:32px;z-index:3;
  background:url("data:image/svg+xml;base64,") center/contain no-repeat;pointer-events:none;transform:rotate(-18deg);filter:drop-shadow(0 3px 4px rgba(0,0,0,.22))}

/* 花笺（角色）*/
#chat .mes:not(.smallSysMes) > .mes_block{position:relative;width:100%;box-sizing:border-box;padding:14px 20px 34px 20px!important;margin:0!important;border-radius:6px 26px 6px 26px;
  background:url("data:image/svg+xml;base64,") right -10px bottom -6px/170px no-repeat,var(--xu-noise),linear-gradient(170deg,rgba(251,250,247,.97),rgba(240,240,236,.95));
  box-shadow:inset 0 0 0 4px rgba(251,250,247,.9),inset 0 0 0 5px var(--xu-line),var(--xu-shadow)}
/* 水面（用户）*/
#chat .mes[is_user="true"]:not(.smallSysMes) > .mes_block{border-radius:26px 6px 26px 6px;
  background:var(--xu-dust),linear-gradient(160deg,#2547bd,#16308a 70%,var(--xu-deep));
  box-shadow:inset 0 0 0 4px rgba(18,42,120,.55),inset 0 0 0 5px rgba(236,215,156,.45),0 10px 26px rgba(10,24,70,.35)}

/* 名字行 */
#chat .mes .ch_name{padding-left:74px;padding-right:44px;min-height:30px}
#chat .mes[is_user="true"] .ch_name{padding-left:4px;padding-right:74px}
#chat .mes .name_text{font:22px/1.2 var(--xu-title)!important;color:var(--xu-blue)!important;letter-spacing:.12em;text-shadow:none!important}
#chat .mes[is_user="true"] .name_text{color:#fff!important}
#chat .mes .timestamp{font:italic 12.5px/1 var(--xu-latin)!important;letter-spacing:.1em;color:var(--xu-mist)!important;margin-left:8px;opacity:1!important}
#chat .mes[is_user="true"] .timestamp{color:var(--xu-gold-soft)!important}
#chat .mes .mes_ghost{color:var(--xu-gold)!important}
#chat .mes .mes_buttons{color:var(--xu-mist)!important}
#chat .mes .mes_buttons .mes_button{opacity:.6;filter:none!important;transition:opacity .2s,color .2s}
#chat .mes .mes_buttons .mes_button:hover{opacity:1;color:var(--xu-blue)}
#chat .mes .mes_button:focus-visible{outline:none;box-shadow:var(--xu-focus);border-radius:6px;opacity:1}
#chat .mes .extraMesButtons{background:transparent}
#chat .mes[is_user="true"] .mes_buttons{color:#d7def6!important}
#chat .mes[is_user="true"] .mes_buttons .mes_button:hover{color:#fff}

/* ─────────── message: text layers ─────────── */
#chat .mes .mes_text{margin-top:10px;padding:12px 0 4px!important;font:15px/1.95 var(--xu-body)!important;font-weight:400!important;letter-spacing:.08em;color:var(--xu-ink)!important;
  background:linear-gradient(90deg,transparent,var(--xu-line) 20%,var(--xu-line) 80%,transparent) top/100% 1px no-repeat}
#chat .mes .mes_text p{margin:0 0 .85em}
#chat .mes .mes_text p:last-child{margin-bottom:0}
#chat .mes .mes_text q{color:var(--xu-blue)!important;font-weight:500}
#chat .mes .mes_text em,#chat .mes .mes_text i{font-style:normal;color:var(--xu-mist)!important;text-decoration:underline wavy rgba(31,63,174,.24) 1px;text-underline-offset:6px;text-decoration-skip-ink:none}
#chat .mes .mes_text q em,#chat .mes .mes_text q i{color:inherit!important}
#chat .mes .mes_text u{text-decoration:underline dotted var(--xu-gold) 1.5px;text-underline-offset:5px;color:inherit!important}
#chat .mes .mes_text strong,#chat .mes .mes_text b{font-weight:600;color:var(--xu-deep);-webkit-text-emphasis:dot var(--xu-gold);text-emphasis:dot var(--xu-gold);-webkit-text-emphasis-position:under right;text-emphasis-position:under right}
#chat .mes .mes_text blockquote{margin:.6em 0 1em;padding:.5em 1em;border:3px double var(--xu-line);border-radius:4px 16px 4px 16px;background:var(--xu-wash);color:var(--xu-mist);font-size:.93em;box-decoration-break:clone;-webkit-box-decoration-break:clone}
#chat .mes .mes_text hr{opacity:1;border:0;height:12px;margin:1em 0;background:radial-gradient(circle,var(--xu-gold) 1.6px,transparent 2.2px) center/100% 100% no-repeat,linear-gradient(90deg,transparent,var(--xu-line) 25%,transparent 45%,transparent 55%,var(--xu-line) 75%,transparent) center/100% 1px no-repeat}
#chat .mes .mes_text a{color:var(--xu-blue);text-decoration:underline dotted;text-underline-offset:4px}
#chat .mes .mes_text h1,#chat .mes .mes_text h2,#chat .mes .mes_text h3,#chat .mes .mes_text h4{font-family:var(--xu-title);font-weight:400;color:var(--xu-blue);letter-spacing:.15em;margin:.6em 0 .4em}
#chat .mes .mes_text ul,#chat .mes .mes_text ol{padding-left:1.4em}
#chat .mes .mes_text li::marker{color:var(--xu-gold)}
#chat .mes .mes_text table{border-collapse:collapse;font-size:.92em}
#chat .mes .mes_text th,#chat .mes .mes_text td{border:1px solid var(--xu-line);padding:4px 8px}
#chat .mes .mes_text th{background:var(--xu-wash);font-family:var(--xu-title);font-weight:400;color:var(--xu-blue)}
#chat .mes .mes_text img{border-radius:6px 18px 6px 18px}
/* 用户水面上的文字 */
#chat .mes[is_user="true"] .mes_text{color:#eef2ff!important;background-image:linear-gradient(90deg,transparent,rgba(236,215,156,.45) 20%,rgba(236,215,156,.45) 80%,transparent)}
#chat .mes[is_user="true"] .mes_text q{color:var(--xu-gold-soft)!important}
#chat .mes[is_user="true"] .mes_text em,#chat .mes[is_user="true"] .mes_text i{color:#c7d2f6!important;text-decoration-color:rgba(236,215,156,.6)}
#chat .mes[is_user="true"] .mes_text strong,#chat .mes[is_user="true"] .mes_text b{color:#fff}
#chat .mes[is_user="true"] .mes_text blockquote{border-color:rgba(236,215,156,.45);background:rgba(255,255,255,.07);color:#d9e0fa}
#chat .mes[is_user="true"] .mes_text a,#chat .mes[is_user="true"] .mes_text h1,#chat .mes[is_user="true"] .mes_text h2,#chat .mes[is_user="true"] .mes_text h3{color:var(--xu-gold-soft)}

/* 代码 */
#chat .mes_text code{font-family:var(--monoFontFamily);background:var(--xu-wash-2);color:var(--xu-deep);border:0;border-radius:4px;padding:.1em .35em;font-size:.88em;letter-spacing:0}
#chat .mes[is_user="true"] .mes_text code{background:rgba(255,255,255,.14);color:#fff}
#chat .mes_text pre{background:var(--xu-deep)!important;border:1px solid rgba(236,215,156,.35);border-radius:6px 16px 6px 16px;padding:10px 12px;overflow-x:auto;box-shadow:var(--xu-shadow-sm)}
#chat .mes_text pre code,#chat .mes_text pre code.hljs{background:transparent!important;color:#e8edff!important;padding:0;font-size:13px;line-height:1.6}

/* 思考块 */
#chat .mes_reasoning_details{margin:10px 0 2px;border-radius:12px;background:var(--xu-wash);box-shadow:inset 0 0 0 1px var(--xu-line-soft)}
#chat .mes_reasoning_summary{padding:4px 12px;color:var(--xu-blue)}
#chat .mes_reasoning_header,#chat .mes_reasoning_header_title{font-family:var(--xu-title)!important;letter-spacing:.15em;color:var(--xu-blue)!important;opacity:1;background:transparent!important;border:0!important}
#chat .mes_reasoning_arrow{color:var(--xu-gold)!important}
#chat .mes_reasoning{padding:4px 14px 10px!important;color:var(--xu-mist)!important;font:13.5px/1.85 var(--xu-body)!important;letter-spacing:.05em}
#chat .mes_reasoning q{color:var(--xu-blue)!important}
#chat .mes[is_user="true"] .mes_reasoning_details{background:rgba(255,255,255,.08)}

/* 编辑态 */
#chat .mes .edit_textarea,#chat .mes .reasoning_edit_textarea{background:rgba(255,255,255,.85)!important;color:var(--xu-ink)!important;border:1px solid var(--xu-line)!important;border-radius:10px!important;
  font:15px/1.85 var(--xu-body)!important;letter-spacing:.05em;padding:8px 10px!important;box-shadow:inset 0 1px 3px rgba(18,42,120,.08)!important;outline:none}
#chat .mes .edit_textarea:focus-visible,#chat .mes .reasoning_edit_textarea:focus-visible{box-shadow:var(--xu-focus)!important}
#chat .mes .mes_edit_buttons{gap:4px}
#chat .mes .mes_edit_buttons .menu_button{background:var(--xu-silk-2)!important;color:var(--xu-blue)!important;border:1px solid var(--xu-line)!important;border-radius:50%!important;width:28px;height:28px;padding:0;opacity:1;filter:none!important}
#chat .mes .mes_edit_buttons .menu_button:hover{background:var(--xu-blue)!important;color:#fff!important}
#chat .mes .mes_edit_buttons .mes_edit_delete:hover{background:var(--xu-err)!important}

/* 滑动切换 */
#chat .mes .swipe_left,#chat .mes .swipe_right{color:var(--xu-blue)!important;opacity:.45;filter:none!important;font-size:16px}
#chat .mes .swipe_left{left:22px!important;bottom:8px!important}
#chat .mes .swipeRightBlock{right:12px!important;bottom:4px!important}
#chat .mes .swipes-counter{color:var(--xu-blue)!important;font:italic 13px/1 var(--xu-latin)!important;letter-spacing:.1em;opacity:.6}
#chat .last_swipe :is(.swipes-counter,.swipe_right){opacity:.9}
#chat .mes .swipe_left:hover,#chat .mes .swipe_right:hover{opacity:1}
/* 用户消息若有滑动 */
#chat .mes[is_user="true"] :is(.swipe_left,.swipe_right,.swipes-counter){color:var(--xu-gold-soft)!important}

/* 选中 / 删除模式 */
#chat .mes.selected > .mes_block{box-shadow:inset 0 0 0 4px rgba(251,250,247,.9),inset 0 0 0 6px var(--xu-err),var(--xu-shadow)!important}
#chat .mes .del_checkbox{align-self:center;margin:4px 0 0!important}

/* 系统小消息 */
#chat .mes.smallSysMes{background:var(--xu-paper)!important;border-radius:999px;margin:16px auto!important;width:auto;max-width:86%;box-shadow:inset 0 0 0 1px var(--xu-line),var(--xu-shadow-sm)!important;border:0!important}
#chat .mes.smallSysMes .mes_text{color:var(--xu-mist)!important;font:13px/1.7 var(--xu-body)!important;letter-spacing:.08em}

/* ─────────── input ─────────── */
#form_sheld{background:transparent!important}
#send_form{border:0!important;border-radius:28px!important;margin:0 auto 8px!important;width:calc(100% - 16px)!important;box-sizing:border-box;
  background:var(--xu-noise),rgba(251,250,247,.96)!important;backdrop-filter:none!important;
  box-shadow:inset 0 0 0 3px rgba(251,250,247,.9),inset 0 0 0 4px var(--xu-line),0 8px 22px rgba(18,42,120,.25)!important}
#send_form.no-connection{box-shadow:inset 0 0 0 3px rgba(251,250,247,.9),inset 0 0 0 4px rgba(155,53,80,.55),0 8px 22px rgba(18,42,120,.25)!important}
#send_textarea{font:15px/1.6 var(--xu-body)!important;color:var(--xu-ink)!important;letter-spacing:.06em;background:transparent!important;border:0!important;box-shadow:none!important}
#send_textarea::placeholder{color:#6f7eaa!important;font-family:var(--xu-title);letter-spacing:.06em;opacity:1;text-overflow:ellipsis;white-space:nowrap}
#send_textarea:focus-visible{outline:none!important}
#leftSendForm,#rightSendForm{flex-wrap:nowrap!important;flex-shrink:0;width:auto!important;height:auto!important;align-items:center}
/* 兼容 QR助手 等往发送栏塞按钮的插件：输入框可以让位，按钮不被挤出屏幕 */
#nonQRFormItems{min-width:0;max-width:100%}
#send_textarea{min-width:0!important;flex:1 1 0!important;width:0;contain:inline-size}
#rightSendForm > #quick-reply-rocket-button{flex:none!important;width:32px!important;min-width:32px;font-size:19px!important;opacity:.9;margin-right:2px}
#rightSendForm > #quick-reply-rocket-button img{border-radius:50%}
@media (max-width:420px){#leftSendForm > div,#rightSendForm > div:not(.mes_stop):not(#send_but){font-size:19px!important}}
#leftSendForm > div,#rightSendForm > div{color:var(--xu-blue)!important;opacity:.85;filter:none!important}
#leftSendForm > div:hover,#rightSendForm > div:hover{opacity:1}
#leftSendForm > div:focus-visible,#rightSendForm > div:focus-visible{outline:none;box-shadow:var(--xu-focus);border-radius:50%}
#send_but{width:36px!important;height:36px!important;line-height:36px!important;text-align:center;border-radius:50%;padding:0!important;margin-left:4px;
  background:radial-gradient(circle at 35% 30%,#3b5fd0,#16308a)!important;color:#fff!important;opacity:1!important;font-size:15px!important;
  box-shadow:0 0 0 3px var(--xu-silk-2),0 0 0 4px var(--xu-line),0 0 0 9px rgba(31,63,174,.08)}
#mes_stop{color:var(--xu-err)!important;opacity:1!important}
#mes_stop .fa-circle-stop{color:var(--xu-err)!important}

/* ─────────── panels / drawers ─────────── */
.drawer-content,#left-nav-panel,#right-nav-panel,#floatingPrompt,#cfgConfig,#logprobsViewer,#movingDivs > div,.popup,dialog.popup,.zoomed_avatar_container,#select_chat_popup{
  background:var(--xu-noise),rgba(244,243,239,.97)!important;color:var(--xu-ink)!important;
  border:0!important;box-shadow:inset 0 0 0 3px rgba(251,250,247,.85),inset 0 0 0 4px var(--xu-line),0 14px 34px rgba(18,42,120,.28)!important;
  backdrop-filter:none!important}
.drawer-content,#left-nav-panel,#right-nav-panel,.popup,dialog.popup{border-radius:8px 22px 8px 22px!important}
.drawer-content h3,.drawer-content h4,#left-nav-panel h3,#left-nav-panel h4,#right-nav-panel h3,#right-nav-panel h4,.popup h3,.popup h4,.popup h2{
  font-family:var(--xu-title)!important;font-weight:400!important;color:var(--xu-blue)!important;letter-spacing:.15em}
.drawer-content small,.drawer-content .note,.popup small{color:var(--xu-mist)}
.drawer-content a,.popup a{color:var(--xu-blue)}
.drawer-content hr,.popup hr,#left-nav-panel hr,#right-nav-panel hr{border:0!important;height:1px;background:linear-gradient(90deg,transparent,var(--xu-line),transparent)!important;opacity:1}
.drawer-content .fa-solid,.drawer-content .fa-regular,.popup .fa-solid{filter:none}
.panelControlBar .drawer-icon,.panelControlBar .fa-solid{color:var(--xu-blue)!important;opacity:.7}
.panelControlBar .fa-solid:hover{opacity:1}

/* 折叠栏：替换官方灰色渐变 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader{
  background:var(--xu-dust),linear-gradient(120deg,#16308a,var(--xu-blue) 60%,#2a4fc4)!important;
  border:0!important;border-radius:6px 18px 6px 18px!important;
  box-shadow:inset 0 0 0 3px rgba(18,42,120,.5),inset 0 0 0 4px rgba(236,215,156,.4)!important;
  color:#fff!important;font-family:var(--xu-title)!important;font-weight:400!important;letter-spacing:.14em!important}
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header{padding:8px 12px!important}
#user-settings-block h4,.standoutHeader{padding:5px 12px!important}
#extensions_settings .inline-drawer-header b,#extensions_settings2 .inline-drawer-header b,
#extensions_settings .inline-drawer-header *,#extensions_settings2 .inline-drawer-header *,
.standoutHeader *{color:#fff!important;font-weight:400}
.standoutHeader .menu_button,#extensions_settings .inline-drawer-header .menu_button,#extensions_settings2 .inline-drawer-header .menu_button,#user-settings-block h4 .menu_button{color:var(--xu-blue)!important;background:var(--xu-silk-2)!important}
.standoutHeader .menu_button *,#extensions_settings .inline-drawer-header .menu_button *,#extensions_settings2 .inline-drawer-header .menu_button *{color:inherit!important}
.standoutHeader .menu_button:hover,#user-settings-block h4 .menu_button:hover{color:#fff!important;background:var(--xu-deep)!important}
#extensions_settings .inline-drawer-header b,#extensions_settings2 .inline-drawer-header b{font-family:var(--xu-title)!important;font-size:16px;letter-spacing:.14em}
#extensions_settings .inline-drawer-icon,#extensions_settings2 .inline-drawer-icon,.standoutHeader .inline-drawer-icon{color:var(--xu-gold-soft)!important;filter:none!important}
#extensions_settings .inline-drawer-header:hover,#extensions_settings2 .inline-drawer-header:hover,.standoutHeader:hover{filter:brightness(1.08)}
#extensions_settings .inline-drawer-header:focus-visible,#extensions_settings2 .inline-drawer-header:focus-visible{outline:none;box-shadow:var(--xu-focus)!important}
#extensions_settings .inline-drawer-content,#extensions_settings2 .inline-drawer-content{padding:8px 10px 10px!important;color:var(--xu-ink)}
/* 其余普通折叠标题 */
.inline-drawer-header{color:var(--xu-ink)}
.inline-drawer-icon{color:var(--xu-blue);filter:none!important}

/* ─────────── controls ─────────── */
.text_pole,textarea.text_pole,select,.drawer-content textarea,.popup textarea,.popup input[type="text"],.popup input[type="number"],.popup input[type="search"],
.drawer-content input[type="text"],.drawer-content input[type="number"],.drawer-content input[type="search"],.drawer-content input[type="password"],.drawer-content input[type="url"]{
  background-color:rgba(255,255,255,.72)!important;color:var(--xu-ink)!important;border:1px solid var(--xu-line)!important;border-radius:10px!important;
  font-family:var(--xu-body);box-shadow:none!important;filter:none!important}
.text_pole::placeholder,textarea::placeholder,input::placeholder{color:var(--xu-faint)!important;opacity:1}
.text_pole:focus-visible,select:focus-visible,textarea:focus-visible,input:focus-visible{outline:none!important;box-shadow:var(--xu-focus)!important}
select option{background:var(--xu-silk-2)!important;color:var(--xu-ink)!important}
select option:checked{background:var(--xu-wash-2)!important;color:var(--xu-blue)!important}

.menu_button{background:var(--xu-silk-2)!important;color:var(--xu-blue)!important;border:1px solid var(--xu-line)!important;border-radius:10px!important;
  filter:none!important;box-shadow:none!important;letter-spacing:.04em}
.menu_button:not([class*="fa-"]){font-family:var(--xu-body)}
.menu_button:not(.disabled):not([disabled]):hover,.menu_button:not(.disabled):not([disabled]).active,.menu_button.toggleEnabled,.menu_button.redOverlayGlow{background:var(--xu-blue)!important;color:#fff!important;border-color:var(--xu-blue)!important}
.menu_button.disabled,.menu_button[disabled]{opacity:var(--xu-disabled)!important;cursor:not-allowed}
.menu_button:focus-visible{outline:none!important;box-shadow:var(--xu-focus)!important}
.menu_button.caution,.menu_button.redWarningBG{color:var(--xu-err)!important;border-color:rgba(155,53,80,.4)!important}
.menu_button.caution:hover,.menu_button.redWarningBG:hover{background:var(--xu-err)!important;color:#fff!important}
.right_menu_button,.interactable{filter:none}

input[type="checkbox"]{background-color:var(--xu-silk-2)!important;border:1px solid var(--xu-line)!important;outline:none!important;box-shadow:none!important;filter:none!important;border-radius:4px}
input[type="checkbox"]::before{box-shadow:inset 1em 1em #fbfaf7!important}
input[type="checkbox"]:checked{background-color:var(--xu-blue)!important;border-color:var(--xu-blue)!important}
input[type="checkbox"]:disabled{opacity:var(--xu-disabled)}
input[type="checkbox"]:focus-visible{box-shadow:var(--xu-focus)!important}
input[type="radio"]{accent-color:var(--xu-blue)}

input[type="range"]{height:2px!important;background:var(--xu-line)!important;box-shadow:none!important;filter:none!important;border-radius:2px}
input[type="range"]::-webkit-slider-thumb{width:20px!important;height:20px!important;border:0!important;border-radius:50%;
  background:url("data:image/svg+xml;base64,") center/120% no-repeat,var(--xu-silk-2)!important;box-shadow:0 0 0 1px var(--xu-line),0 2px 6px rgba(18,42,120,.3)!important}
input[type="range"]::-moz-range-thumb{width:20px;height:20px;border:0;border-radius:50%;background:url("data:image/svg+xml;base64,") center/120% no-repeat,var(--xu-silk-2);box-shadow:0 0 0 1px var(--xu-line)}
input[type="range"]:focus-visible{box-shadow:var(--xu-focus)!important}
.range-block-counter input,.neo-range-input{background:transparent!important;color:var(--xu-blue)!important;font-family:var(--xu-latin);font-style:italic}

/* tags */
.tag{background-color:var(--xu-wash);border:1px solid var(--xu-line)!important;color:var(--xu-blue);border-radius:999px!important;filter:none!important;opacity:1}
.tag.selected,.tag.actionable.selected{background-color:var(--xu-blue)!important;color:#fff!important}
.tag.excluded{border-color:rgba(155,53,80,.5)!important;color:var(--xu-err)!important}
.tag_remove{color:inherit;opacity:.7}
.tags_inline .tag{font-size:.82em}

/* select2 */
.select2-container .select2-selection,.select2-container--default .select2-selection--multiple,.select2-container--default .select2-selection--single{
  background-color:rgba(255,255,255,.72)!important;border:1px solid var(--xu-line)!important;border-radius:10px!important;color:var(--xu-ink)!important}
.select2-container--default .select2-selection--single .select2-selection__rendered{color:var(--xu-ink)!important}
.select2-container--default .select2-selection--multiple .select2-selection__choice{background:var(--xu-wash)!important;border:1px solid var(--xu-line)!important;color:var(--xu-blue)!important;border-radius:999px!important}
.select2-dropdown{background:var(--xu-silk-2)!important;border:1px solid var(--xu-line)!important;border-radius:10px!important;color:var(--xu-ink)!important;box-shadow:var(--xu-shadow-sm)}
.select2-results__option{color:var(--xu-ink)!important}
.select2-container--default .select2-results__option--highlighted.select2-results__option--selectable{background:var(--xu-blue)!important;color:#fff!important}
.select2-container--default .select2-results__option--selected{background:var(--xu-wash-2)!important}
.select2-search__field{color:var(--xu-ink)!important}

/* 角色/群组列表 */
.character_select,.group_select,.bogus_folder_select{border-radius:12px;transition:background .2s}
.character_select:hover,.group_select:hover,.bogus_folder_select:hover{background:var(--xu-wash)!important}
.character_select.is_fav .ch_name,.character_select .ch_name{color:var(--xu-ink)}
.character_select .avatar img,.group_select .avatar img{border:1px solid var(--xu-line)!important;box-shadow:0 2px 6px rgba(18,42,120,.2)!important}
.avatar.interactable{opacity:.85}
#rm_print_characters_block .ch_name{font-family:var(--xu-title);letter-spacing:.08em;color:var(--xu-blue)}
.ch_description,.character_select .ch_description{color:var(--xu-mist)!important}

/* 历史聊天 / 滑动选择 */
.select_chat_block,.swipe_picker_block{background:rgba(255,255,255,.6)!important;border:1px solid var(--xu-line)!important;border-radius:10px 18px 10px 18px!important;color:var(--xu-ink)!important}
.select_chat_block:hover,.swipe_picker_block:hover{background:var(--xu-wash-2)!important}
.select_chat_block[highlight],.swipe_picker_block[highlight]{background:rgba(31,63,174,.16)!important;box-shadow:inset 0 0 0 1px var(--xu-blue)}
.select_chat_block_filename{font-family:var(--xu-title);color:var(--xu-blue)!important;letter-spacing:.06em}
.select_chat_block_mes{color:var(--xu-mist)!important}
.select_chat_info{color:var(--xu-faint)!important}

/* prompt manager：去掉官方黑色投影光晕，启用/禁用一眼分清 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt{background:rgba(255,255,255,.62)!important;border:1px solid var(--xu-line-soft)!important;border-radius:8px 14px 8px 14px!important;color:var(--xu-ink)!important}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover{background:var(--xu-wash-2)!important}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span{filter:none!important;opacity:.85!important;color:var(--xu-blue)}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span:hover,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span:hover{opacity:1!important}
#completion_prompt_manager .prompt-manager-detach-action,#completion_prompt_manager .prompt-manager-edit-action,#completion_prompt_manager .prompt-manager-inspect-action{color:var(--xu-blue)!important}
#completion_prompt_manager .fa-trash-can,#completion_prompt_manager .caution{color:var(--xu-err)!important}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action{color:var(--xu-blue)!important}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled{background:rgba(244,243,239,.55)!important;border:1px dashed var(--xu-line)!important}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action{color:var(--xu-faint)!important}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action{color:var(--xu-faint)!important}
#completion_prompt_manager .completion_prompt_manager_header_advanced span{filter:none!important}
#completion_prompt_manager .completion_prompt_manager_list_head{color:var(--xu-blue)!important;font-family:var(--xu-title)}
#completion_prompt_manager .drag-handle{color:var(--xu-mist)!important;opacity:.8}
#completion_prompt_manager .prompt_manager_prompt_tokens,#completion_prompt_manager .completion_prompt_manager_prompt_tokens{color:var(--xu-mist)!important}
.completion_prompt_manager_popup_entry,#completion_prompt_manager_popup{background:var(--xu-silk)!important;color:var(--xu-ink)!important}

/* 欢迎页：版本标题 + 最近聊天，铺成一张花笺 */
#chat > .welcomePanel{margin:10px 0 6px;padding:14px 14px 12px!important;border-radius:8px 22px 8px 22px;color:var(--xu-ink)!important;
  background:var(--xu-noise),rgba(251,250,247,.96);box-shadow:inset 0 0 0 4px rgba(251,250,247,.9),inset 0 0 0 5px var(--xu-line),var(--xu-shadow)}
#chat > .welcomePanel .welcomeHeaderVersionDisplay{font:400 18px/1.3 var(--xu-title)!important;color:var(--xu-blue)!important;letter-spacing:.08em}
#chat > .welcomePanel .recentChatsTitle{font:400 17px/1.3 var(--xu-title)!important;color:var(--xu-blue)!important;letter-spacing:.2em}
#chat > .welcomePanel .mes_button{color:var(--xu-blue)!important;opacity:.75}
#chat > .welcomePanel .welcomeShortcutsSeparator{color:var(--xu-line)!important}
#chat > .welcomePanel .recentChat{background:rgba(255,255,255,.7)!important;border:1px solid var(--xu-line-soft)!important;border-radius:8px 16px 8px 16px!important;color:var(--xu-ink)!important}
#chat > .welcomePanel .recentChat:hover{background:var(--xu-wash-2)!important}
#chat > .welcomePanel .recentChat .chatName{font-family:var(--xu-title);color:var(--xu-blue)!important;letter-spacing:.06em}
#chat > .welcomePanel .recentChat .chatMessage{color:var(--xu-mist)!important}
#chat > .welcomePanel .recentChat .chatStats,#chat > .welcomePanel .recentChat .chatDate,#chat > .welcomePanel .recentChat small{color:var(--xu-faint)!important}
#chat > .welcomePanel .recentChat .avatar img{border:0!important;box-shadow:0 0 0 2px var(--xu-silk-2),0 0 0 3px var(--xu-line)!important}
#chat > .welcomePanel .recentChatPinned{color:var(--xu-gold)!important}
#chat > .welcomePanel .noRecentChat{color:var(--xu-mist)}
#chat > .welcomePanel .showMoreChats{color:var(--xu-blue)!important}

/* world info */
.world_entry{border-radius:12px;box-shadow:inset 0 0 0 1px var(--xu-line-soft)}
.world_entry .inline-drawer-header{background:transparent}
.world_entry_form_control small,.world_entry_form_control label{color:var(--xu-mist)}

/* ─────────── 浮层：菜单 / 弹窗 / 通知 ─────────── */
.options-content,.list-group,#extensionsMenu,.ctx-menu,.context-menu,.dropdown-menu,.autoComplete,.slashCommandAutoComplete{
  background:var(--xu-noise),var(--xu-silk-2)!important;color:var(--xu-ink)!important;border:0!important;border-radius:6px 18px 6px 18px!important;
  box-shadow:inset 0 0 0 1px var(--xu-line),0 10px 28px rgba(18,42,120,.28)!important;backdrop-filter:none!important}
.options-content a,.list-group-item,.list-group > div,#extensionsMenu > div,#extensionsMenu .list-group-item{color:var(--xu-ink)!important;font-family:var(--xu-body);letter-spacing:.06em;opacity:1}
.options-content a:hover,.list-group-item:hover,.list-group > div:hover,#extensionsMenu .list-group-item:hover{background:var(--xu-wash-2)!important;color:var(--xu-blue)!important}
.options-content i,.extensionsMenuExtensionButton,.list-group-item i,#extensionsMenu i{color:var(--xu-blue)!important;filter:none!important;opacity:1}
.options-content hr{background:linear-gradient(90deg,transparent,var(--xu-line),transparent)!important;border:0;height:1px;opacity:1}

dialog.popup::backdrop,.popup::backdrop{background:rgba(15,36,104,.38)!important;backdrop-filter:blur(3px)}
#shadow_popup,#shadow_select_chat_popup{background:rgba(15,36,104,.3)!important}
.popup .popup-body,.popup .popup-content{color:var(--xu-ink)!important}
.popup .popup-controls{gap:8px}
.popup .popup-button-ok{background:var(--xu-blue)!important;color:#fff!important;border-color:var(--xu-blue)!important}
.popup .popup-button-ok:hover{background:var(--xu-deep)!important}

#toast-container > .toast,#toast-container > div{background-color:var(--xu-blue)!important;color:#fff!important;border:0!important;border-radius:8px 18px 8px 18px!important;
  box-shadow:inset 0 0 0 3px rgba(18,42,120,.4),inset 0 0 0 4px rgba(236,215,156,.45),0 10px 24px rgba(18,42,120,.3)!important;opacity:.97!important;font-family:var(--xu-body);letter-spacing:.05em}
#toast-container > .toast-success{background-color:var(--xu-ok)!important}
#toast-container > .toast-warning{background-color:var(--xu-warn)!important}
#toast-container > .toast-error{background-color:var(--xu-err)!important}
#toast-container .toast-title{font-family:var(--xu-title);font-weight:400;letter-spacing:.12em}

/* 头像放大 */
.zoomed_avatar img{border-radius:8px 26px 8px 26px!important;box-shadow:0 0 0 4px var(--xu-silk-2),0 0 0 5px var(--xu-blue),0 18px 40px rgba(18,42,120,.4)!important}

/* ─────────── mobile ─────────── */
@media (max-width:1000px){
  #chat{padding:14px 8px 14px!important}
  #chat .mes:not(.smallSysMes) > .mes_block{padding:14px 16px 34px!important}
  #chat .mes .mes_text{font-size:15px!important;letter-spacing:.06em}
  .drawer-content,#left-nav-panel,#right-nav-panel{border-radius:0 0 18px 18px!important}
}

